export const GROUP_SETTINGS_SCHEMA_VERSION = 1 as const;

export const DEFAULT_GROUPS = Object.freeze([
  Object.freeze({ id: 'character-lorebooks', name: '角色卡世界书' }),
  Object.freeze({ id: 'functional-lorebooks', name: '功能性世界书' }),
]);

export interface LorebookGroup {
  readonly id: string;
  readonly name: string;
  readonly bookNames: readonly string[];
}

export interface LorebookGroupSettings {
  readonly schemaVersion: typeof GROUP_SETTINGS_SCHEMA_VERSION;
  readonly groups: readonly LorebookGroup[];
}

export type GroupSettingsLoadSource = 'missing' | 'current' | 'migrated' | 'invalid';

export interface GroupSettingsLoadResult {
  readonly settings: LorebookGroupSettings;
  readonly source: GroupSettingsLoadSource;
  readonly shouldPersist: boolean;
  readonly issue?: string;
}

interface LegacyGroupSettingsV0 {
  readonly schemaVersion: 0;
  readonly groups: readonly {
    readonly id: string;
    readonly name: string;
    readonly worldNames: readonly string[];
  }[];
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
}

function normalizedText(value: unknown): string | undefined {
  if (typeof value !== 'string') {
    return undefined;
  }

  const normalized = value.trim();
  return normalized.length > 0 ? normalized : undefined;
}

function exactNonBlankText(value: unknown): string | undefined {
  if (typeof value !== 'string' || value.trim().length === 0) {
    return undefined;
  }

  return value;
}

function parseUniqueNames(value: unknown): readonly string[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const names: string[] = [];
  const seen = new Set<string>();
  for (const item of value) {
    const name = exactNonBlankText(item);
    if (!name || seen.has(name)) {
      return undefined;
    }

    seen.add(name);
    names.push(name);
  }

  return Object.freeze(names);
}

function freezeSettings(groups: readonly LorebookGroup[]): LorebookGroupSettings {
  return Object.freeze({
    schemaVersion: GROUP_SETTINGS_SCHEMA_VERSION,
    groups: Object.freeze(
      groups.map((group) =>
        Object.freeze({
          id: group.id,
          name: group.name,
          bookNames: Object.freeze([...group.bookNames]),
        }),
      ),
    ),
  });
}

export function createDefaultGroupSettings(): LorebookGroupSettings {
  return freezeSettings(
    DEFAULT_GROUPS.map((group) => ({
      ...group,
      bookNames: [],
    })),
  );
}

function parseGroups(
  value: unknown,
  bookNamesKey: 'bookNames' | 'worldNames',
): readonly LorebookGroup[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const groups: LorebookGroup[] = [];
  const ids = new Set<string>();
  const normalizedNames = new Set<string>();

  for (const item of value) {
    const record = asRecord(item);
    const id = normalizedText(record?.id);
    const name = normalizedText(record?.name);
    const bookNames = parseUniqueNames(record?.[bookNamesKey]);
    const normalizedName = name?.toLocaleLowerCase();
    if (
      !id ||
      !name ||
      !bookNames ||
      !normalizedName ||
      ids.has(id) ||
      normalizedNames.has(normalizedName)
    ) {
      return undefined;
    }

    ids.add(id);
    normalizedNames.add(normalizedName);
    groups.push({ id, name, bookNames });
  }

  return groups;
}

function parseCurrentSettings(value: Record<string, unknown>): LorebookGroupSettings | undefined {
  if (value.schemaVersion !== GROUP_SETTINGS_SCHEMA_VERSION) {
    return undefined;
  }

  const groups = parseGroups(value.groups, 'bookNames');
  return groups ? freezeSettings(groups) : undefined;
}

function parseLegacySettings(value: Record<string, unknown>): LegacyGroupSettingsV0 | undefined {
  if (value.schemaVersion !== 0) {
    return undefined;
  }

  const groups = parseGroups(value.groups, 'worldNames');
  if (!groups) {
    return undefined;
  }

  return {
    schemaVersion: 0,
    groups: groups.map((group) => ({
      id: group.id,
      name: group.name,
      worldNames: group.bookNames,
    })),
  };
}

export function loadGroupSettings(value: unknown): GroupSettingsLoadResult {
  if (value === undefined) {
    return Object.freeze({
      settings: createDefaultGroupSettings(),
      source: 'missing',
      shouldPersist: true,
    });
  }

  const record = asRecord(value);
  if (record) {
    const current = parseCurrentSettings(record);
    if (current) {
      return Object.freeze({ settings: current, source: 'current', shouldPersist: false });
    }

    const legacy = parseLegacySettings(record);
    if (legacy) {
      return Object.freeze({
        settings: freezeSettings(
          legacy.groups.map((group) => ({
            id: group.id,
            name: group.name,
            bookNames: group.worldNames,
          })),
        ),
        source: 'migrated',
        shouldPersist: true,
      });
    }
  }

  return Object.freeze({
    settings: createDefaultGroupSettings(),
    source: 'invalid',
    shouldPersist: false,
    issue: '分组数据格式异常，已停止写入以保护原数据。',
  });
}

function assertNonEmpty(value: string, label: string): string {
  const normalized = normalizedText(value);
  if (!normalized) {
    throw new Error(`${label}不能为空。`);
  }

  return normalized;
}

function assertExactNonBlank(value: string, label: string): string {
  const exactValue = exactNonBlankText(value);
  if (!exactValue) {
    throw new Error(`${label}不能为空。`);
  }

  return exactValue;
}

function assertGroupExists(settings: LorebookGroupSettings, groupId: string): number {
  const index = settings.groups.findIndex((group) => group.id === groupId);
  if (index < 0) {
    throw new Error('找不到指定分组。');
  }

  return index;
}

function assertUniqueGroupName(
  settings: LorebookGroupSettings,
  name: string,
  exceptGroupId?: string,
): void {
  const normalizedName = name.toLocaleLowerCase();
  if (
    settings.groups.some(
      (group) => group.id !== exceptGroupId && group.name.toLocaleLowerCase() === normalizedName,
    )
  ) {
    throw new Error('分组名称不能重复。');
  }
}

export function createGroup(
  settings: LorebookGroupSettings,
  input: { readonly id: string; readonly name: string },
): LorebookGroupSettings {
  const id = assertNonEmpty(input.id, '分组编号');
  const name = assertNonEmpty(input.name, '分组名称');
  if (settings.groups.some((group) => group.id === id)) {
    throw new Error('分组编号不能重复。');
  }
  assertUniqueGroupName(settings, name);

  return freezeSettings([...settings.groups, { id, name, bookNames: [] }]);
}

export function renameGroup(
  settings: LorebookGroupSettings,
  groupId: string,
  nextNameValue: string,
): LorebookGroupSettings {
  const groupIndex = assertGroupExists(settings, groupId);
  const nextName = assertNonEmpty(nextNameValue, '分组名称');
  assertUniqueGroupName(settings, nextName, groupId);

  return freezeSettings(
    settings.groups.map((group, index) =>
      index === groupIndex ? { ...group, name: nextName } : group,
    ),
  );
}

export function deleteGroup(
  settings: LorebookGroupSettings,
  groupId: string,
): LorebookGroupSettings {
  const groupIndex = assertGroupExists(settings, groupId);
  return freezeSettings(settings.groups.filter((_, index) => index !== groupIndex));
}

export function moveGroup(
  settings: LorebookGroupSettings,
  groupId: string,
  destinationIndex: number,
): LorebookGroupSettings {
  const sourceIndex = assertGroupExists(settings, groupId);
  if (
    !Number.isInteger(destinationIndex) ||
    destinationIndex < 0 ||
    destinationIndex >= settings.groups.length
  ) {
    throw new Error('分组排序位置无效。');
  }

  const groups = [...settings.groups];
  const [group] = groups.splice(sourceIndex, 1);
  if (!group) {
    throw new Error('找不到指定分组。');
  }
  groups.splice(destinationIndex, 0, group);
  return freezeSettings(groups);
}

export function setBookGroupMembership(
  settings: LorebookGroupSettings,
  groupId: string,
  bookNameValue: string,
  assigned: boolean,
): LorebookGroupSettings {
  return setBookGroupMemberships(settings, groupId, [bookNameValue], assigned);
}

export function setBookGroupMemberships(
  settings: LorebookGroupSettings,
  groupId: string,
  bookNameValues: readonly string[],
  assigned: boolean,
): LorebookGroupSettings {
  const groupIndex = assertGroupExists(settings, groupId);
  const bookNames = [
    ...new Set(bookNameValues.map((name) => assertExactNonBlank(name, '世界书名称'))),
  ];
  if (bookNames.length === 0) {
    throw new Error('至少选择一本世界书。');
  }
  const selectedBookNames = new Set(bookNames);

  return freezeSettings(
    settings.groups.map((group, index) => {
      if (index !== groupIndex) {
        return group;
      }

      return {
        ...group,
        bookNames: assigned
          ? [
              ...group.bookNames,
              ...bookNames.filter((bookName) => !group.bookNames.includes(bookName)),
            ]
          : group.bookNames.filter((name) => !selectedBookNames.has(name)),
      };
    }),
  );
}

function uniqueBookNames(worldNames: readonly string[]): string[] {
  const seen = new Set<string>();
  return worldNames.filter((name) => {
    if (name.length === 0 || seen.has(name)) {
      return false;
    }
    seen.add(name);
    return true;
  });
}

export function getUngroupedBookNames(
  settings: LorebookGroupSettings,
  worldNames: readonly string[],
): readonly string[] {
  const assignedNames = new Set(settings.groups.flatMap((group) => group.bookNames));
  return Object.freeze(uniqueBookNames(worldNames).filter((name) => !assignedNames.has(name)));
}
